sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.rental-widget {

  width: 300px;

  margin: 20px auto;

}
 
.rental-link {

  display: block;

  text-decoration: none;

  background-color: #ffffff;

  border: 1px solid #ddd;

  border-radius: 12px;

  padding: 20px;

  text-align: center;

  transition: box-shadow 0.3s, transform 0.3s;

  color: #333;

}
 
.rental-link:hover {

  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.1);

  transform: translateY(-5px);

}
 
.rental-icon {

  font-size: 50px;

  margin-bottom: 15px;

  background: linear-gradient(135deg, #4a90e2, #50e3c2, #b8e986);

  -webkit-background-clip: text;

  -webkit-text-fill-color: transparent;

}
 
.rental-title {

  font-size: 20px;

  margin: 10px 0 5px 0;

}
 
.rental-desc {

  font-size: 14px;

  color: #666;

  margin: 0;

}
